/**
 * The contract `command.tsx` (native) and `command.web.tsx` (cmdk) both implement. Its own module
 * for the usual reason: Metro resolves `./command` to `command.web.tsx` on web, so the web file
 * cannot import shared types from `./command` without importing itself.
 *
 * This is the surface both halves honour — the props cubeui's own `MultiSelect` and shadcn's
 * command-palette examples reach for. The web half widens every part to cmdk's own props on top of
 * it, so a DOM call site written against shadcn's `command` compiles unchanged. What cmdk takes
 * beyond this list is web only, and the native half does not accept it:
 *
 * - **The highlight.** cmdk keeps one item highlighted and moves it with the arrow keys; `value`,
 *   `onValueChange`, `defaultValue`, `loop`, `vimBindings` and `disablePointerSelection` on
 *   `Command` all steer it. A touch screen has no highlight — an item is chosen by pressing it —
 *   so there is nothing on native for them to steer.
 * - **The ranking.** cmdk's default filter is a fuzzy scorer, and it re-sorts the list by score.
 *   The native default is {@link matchesEveryWord}, and the list stays in the order it was
 *   written. A caller who passes `filter` gets the same answer on both halves; a caller who
 *   does not gets the same set of rows, give or take cmdk's fuzziness, in a different order.
 * - **`CommandLoading`**, `CommandGroup`'s `value`, and `Command`'s `asChild`.
 */
import { Children, isValidElement, type ReactNode } from "react";
import type { DialogProps } from "@/components/ui/dialog-base";

/**
 * How much an item matches the search: above `0` is shown, `0` is hidden. cmdk's own signature,
 * so one function serves both halves. `value` is the item's `value` (or its text), `keywords` its
 * `keywords`.
 */
export type CommandFilter = (value: string, search: string, keywords?: string[]) => number;

export type CommandProps = {
  /**
   * The search box's accessible name. cmdk renders it as a hidden `<label>` for its input; on
   * native it is the input's `aria-label`. A placeholder is not a name.
   */
  label?: string | undefined;
  /** Replaces the default match. See {@link CommandFilter}. */
  filter?: CommandFilter | undefined;
  /** Off, every item is drawn whatever is typed — for a caller filtering the list itself. */
  shouldFilter?: boolean | undefined;
  className?: string | undefined;
  children?: ReactNode;
};

export type CommandInputProps = {
  /** Controlled when passed: the search is this, and typing only calls `onValueChange`. */
  value?: string | undefined;
  onValueChange?: ((search: string) => void) | undefined;
  placeholder?: string | undefined;
  disabled?: boolean | undefined;
  autoFocus?: boolean | undefined;
  className?: string | undefined;
};

export type CommandListProps = {
  /** The list's accessible name, as cmdk's `label`. Default {@link COMMAND_LIST_LABEL}. */
  label?: string | undefined;
  className?: string | undefined;
  children?: ReactNode;
};

/** Drawn only while no item matches the search. */
export type CommandEmptyProps = {
  className?: string | undefined;
  children?: ReactNode;
};

export type CommandGroupProps = {
  /** Drawn above the group's items, muted. A string is also the group's accessible name. */
  heading?: ReactNode;
  /** Draw the group even when none of its items match. Its items still filter themselves. */
  forceMount?: boolean | undefined;
  className?: string | undefined;
  children?: ReactNode;
};

export type CommandItemProps = {
  /**
   * What the filter matches and what `onSelect` is handed. Without it the item's text is used —
   * cmdk reads `textContent`, native the string children, however deeply nested. Pass it
   * whenever the row holds more than its name, or the badge beside the name is searched too.
   */
  value?: string | undefined;
  /** More words the filter matches — a synonym, an old name, a code. Never drawn. */
  keywords?: string[] | undefined;
  disabled?: boolean | undefined;
  /** Draw the item whatever the search is — a "Create …" row that must survive the filter. */
  forceMount?: boolean | undefined;
  /** The item was chosen: pressed on native; clicked, or Enter on the highlight, on the web. */
  onSelect?: ((value: string) => void) | undefined;
  className?: string | undefined;
  "aria-label"?: string | undefined;
  /** For a row that toggles — a multi-select's ✓. cmdk leaves it alone; see `MultiSelect`. */
  "aria-checked"?: boolean | undefined;
  "aria-describedby"?: string | undefined;
  children?: ReactNode;
};

/**
 * A rule between groups. Hidden from assistive technology on both halves: a `listbox` may hold
 * only options and groups, so cmdk's `role="separator"` inside one is an axe failure, and a line
 * between two headed groups says nothing the headings do not.
 */
export type CommandSeparatorProps = {
  /** Keep the rule while there is a search. By default it hides, as cmdk's does. */
  alwaysRender?: boolean | undefined;
  className?: string | undefined;
};

export type CommandShortcutProps = {
  className?: string | undefined;
  children?: ReactNode;
};

/** A `Command` in a `Dialog`: the palette. `title` and `description` name it and are not drawn. */
export type CommandDialogProps = DialogProps & {
  title?: string | undefined;
  description?: string | undefined;
  className?: string | undefined;
  showCloseButton?: boolean | undefined;
};

/** cmdk's own default name for its list. */
export const COMMAND_LIST_LABEL = "Suggestions";
export const COMMAND_DIALOG_TITLE = "Command Palette";
export const COMMAND_DIALOG_DESCRIPTION = "Search for a command to run...";

/**
 * The native half's default filter: every whitespace-separated word of the search appears
 * somewhere in the value or the keywords, ignoring case. `1` or `0`, because the native list is
 * not re-sorted — the order is the caller's.
 *
 * The same test `MultiSelect` hands cmdk, so a multi-select filters alike on both halves.
 */
export function matchesEveryWord(value: string, search: string, keywords?: string[]): number {
  const words = search.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
  if (words.length === 0) return 1;
  const target = [value, ...(keywords ?? [])].join(" ").toLocaleLowerCase();
  return words.every((word) => target.includes(word)) ? 1 : 0;
}

/**
 * An item's text, for when it has no `value`: its string and number children, however deeply
 * they sit, joined as `textContent` would join them. What cmdk reads from the DOM, read from the
 * element tree instead, because on native there is no DOM to read.
 */
export function commandItemText(children: ReactNode): string {
  const parts: string[] = [];
  const walk = (node: ReactNode) => {
    for (const child of Children.toArray(node)) {
      if (typeof child === "string" || typeof child === "number") parts.push(String(child));
      else if (isValidElement<{ children?: ReactNode }>(child)) walk(child.props.children);
    }
  };
  walk(children);
  return parts.join("").trim();
}

/**
 * The native command list: a search `Input` over a scrolling list of pressable rows, filtered as
 * you type. `command.web.tsx` is the counterpart, shadcn's parts over `cmdk`, and
 * `command-base.ts` the contract the two share.
 *
 * cmdk has no React Native build, so this is not a port of it but the same parts with the same
 * names and the props cubeui's own call sites use. What it does not do, and why, is in
 * `command-base.ts`: in short, there is no highlighted row for arrow keys to move — a row is
 * chosen by pressing it — and the default filter matches every typed word rather than scoring
 * fuzzily and re-sorting.
 *
 * Each item decides for itself whether it matches, from the search in context, and reports the
 * answer upward. That is how `CommandEmpty` knows the list is empty and a `CommandGroup` knows to
 * hide its heading without either of them walking a tree they cannot see — an item is often
 * wrapped in the caller's own component, as `MultiSelect`'s rows are. An item that does not match
 * stays mounted and draws nothing, so its answer is still there when the search changes back.
 */

import {
  createContext,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useState,
  useSyncExternalStore,
} from "react";
import { Platform, Pressable, type Role, ScrollView, Text, View } from "react-native";
import {
  COMMAND_DIALOG_DESCRIPTION,
  COMMAND_DIALOG_TITLE,
  COMMAND_LIST_LABEL,
  type CommandDialogProps,
  type CommandEmptyProps,
  type CommandFilter,
  type CommandGroupProps,
  type CommandInputProps,
  type CommandItemProps,
  type CommandListProps,
  type CommandProps,
  type CommandSeparatorProps,
  type CommandShortcutProps,
  commandItemText,
  matchesEveryWord,
} from "@/components/ui/command-base";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Search } from "@/components/ui/icons";
import { IconClassContext } from "@/components/ui/icons-base";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

/** Off the screen and still read. `sr-only` is a clip, which the device does not have. */
const SR_ONLY = Platform.select({
  web: "sr-only",
  default: "absolute -m-px h-px w-px overflow-hidden",
});

type Entry = { matches: boolean; shown: boolean; group: string | undefined };

/**
 * What every item said about itself. A store rather than state in `Command`, so an item reporting
 * re-renders only the parts that read a count — the empty message and the groups — and not every
 * other item in the list.
 */
function createItemStore() {
  const entries = new Map<string, Entry>();
  const listeners = new Set<() => void>();
  const notify = () => {
    for (const listener of listeners) listener();
  };
  return {
    set(id: string, entry: Entry) {
      const was = entries.get(id);
      if (was && was.matches === entry.matches && was.shown === entry.shown) return;
      entries.set(id, entry);
      notify();
    },
    remove(id: string) {
      if (entries.delete(id)) notify();
    },
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    /** Items that match the search: what cmdk calls the filtered count. */
    matching() {
      let count = 0;
      for (const entry of entries.values()) if (entry.matches) count++;
      return count;
    },
    /** Items drawn in one group, forced or matching. */
    shownIn(group: string) {
      let count = 0;
      for (const entry of entries.values()) if (entry.group === group && entry.shown) count++;
      return count;
    },
  };
}

type ItemStore = ReturnType<typeof createItemStore>;

type CommandState = {
  label: string | undefined;
  search: string;
  setSearch: (search: string) => void;
  filter: CommandFilter;
  shouldFilter: boolean;
  store: ItemStore;
};

const CommandContext = createContext<CommandState>({
  label: undefined,
  search: "",
  setSearch: () => {},
  filter: matchesEveryWord,
  shouldFilter: true,
  store: createItemStore(),
});

const CommandGroupContext = createContext<string | undefined>(undefined);

function Command({
  label,
  filter = matchesEveryWord,
  shouldFilter = true,
  className,
  children,
}: CommandProps) {
  const [search, setSearch] = useState("");
  const store = useMemo(createItemStore, []);
  return (
    <CommandContext.Provider value={{ label, search, setSearch, filter, shouldFilter, store }}>
      <View className={cn("w-full flex-col overflow-hidden rounded-md bg-popover", className)}>
        {children}
      </View>
    </CommandContext.Provider>
  );
}

function CommandDialog({
  title = COMMAND_DIALOG_TITLE,
  description = COMMAND_DIALOG_DESCRIPTION,
  className,
  showCloseButton = true,
  children,
  ...props
}: CommandDialogProps) {
  return (
    <Dialog {...props}>
      <DialogContent
        className={cn("overflow-hidden p-0", className)}
        showCloseButton={showCloseButton}
      >
        {/* Inside the card, not beside it as shadcn has it: on native everything that is not a
            trigger goes into the `Modal`, and a header outside the card would sit on the
            backdrop. */}
        <DialogHeader className={SR_ONLY}>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <Command>{children}</Command>
      </DialogContent>
    </Dialog>
  );
}

function CommandInput({
  value,
  onValueChange,
  placeholder,
  disabled,
  autoFocus,
  className,
}: CommandInputProps) {
  const { label, search, setSearch } = useContext(CommandContext);

  // A controlled box drives the search; an uncontrolled one writes it as it is typed. cmdk's
  // arrangement, so a caller who holds `value` and clears it clears the filter too.
  useEffect(() => {
    if (value !== undefined) setSearch(value);
  }, [value, setSearch]);

  return (
    <View className="border-b border-border px-1">
      <Input
        type="search"
        value={value ?? search}
        onChangeText={(text) => {
          if (value === undefined) setSearch(text);
          onValueChange?.(text);
        }}
        placeholder={placeholder}
        disabled={disabled}
        autoFocus={autoFocus}
        aria-label={label}
        leading={<Search />}
        className={cn("h-11 border-0 bg-transparent", className)}
      />
    </View>
  );
}

function CommandList({ label = COMMAND_LIST_LABEL, className, children }: CommandListProps) {
  return (
    <ScrollView
      // A press on a row while the keyboard is up is a press on the row. The default spends it
      // dismissing the keyboard, so every choice would take two taps.
      keyboardShouldPersistTaps="handled"
      // ARIA's `listbox`, which react-native-web hands the DOM. React Native's `Role` has no such
      // word and drops one it does not know, so on device the rows sit in a plain `list`.
      role={Platform.OS === "web" ? ("listbox" as Role) : "list"}
      aria-label={label}
      className={cn("max-h-[300px]", className)}
    >
      {children}
    </ScrollView>
  );
}

function CommandEmpty({ className, children }: CommandEmptyProps) {
  const { store } = useContext(CommandContext);
  const matching = useSyncExternalStore(store.subscribe, store.matching, store.matching);
  if (matching > 0) return null;
  return (
    <View className={cn("py-6", className)}>
      {typeof children === "string" ? (
        <Text className="text-center text-sm text-popover-foreground">{children}</Text>
      ) : (
        children
      )}
    </View>
  );
}

function CommandGroup({ heading, forceMount = false, className, children }: CommandGroupProps) {
  const { store } = useContext(CommandContext);
  const id = useId();
  const shownIn = () => store.shownIn(id);
  const shown = useSyncExternalStore(store.subscribe, shownIn, shownIn);
  const hidden = !forceMount && shown === 0;
  return (
    <CommandGroupContext.Provider value={id}>
      {/* Hidden rather than unmounted: the items inside have to stay mounted to say whether they
          match, or a group that emptied could never come back. */}
      <View
        role="group"
        aria-label={typeof heading === "string" ? heading : undefined}
        className={cn("p-1", hidden && "hidden", className)}
      >
        {heading == null ? null : typeof heading === "string" ? (
          <Text className="px-2 py-1.5 text-xs font-medium text-muted-foreground">{heading}</Text>
        ) : (
          heading
        )}
        {children}
      </View>
    </CommandGroupContext.Provider>
  );
}

function CommandSeparator({ alwaysRender = false, className }: CommandSeparatorProps) {
  const { search } = useContext(CommandContext);
  if (search !== "" && !alwaysRender) return null;
  return <View aria-hidden className={cn("-mx-1 h-px bg-border", className)} />;
}

function CommandItem({
  value,
  keywords,
  disabled = false,
  forceMount = false,
  onSelect,
  className,
  "aria-label": ariaLabel,
  "aria-checked": ariaChecked,
  "aria-describedby": ariaDescribedBy,
  children,
}: CommandItemProps) {
  const { search, filter, shouldFilter, store } = useContext(CommandContext);
  const group = useContext(CommandGroupContext);
  const id = useId();
  const itemValue = (value ?? commandItemText(children)).trim();
  const matches = !shouldFilter || search.trim() === "" || filter(itemValue, search, keywords) > 0;
  const shown = matches || forceMount;

  // Before paint, so `CommandEmpty` does not flash "No results" over a list that has rows.
  useLayoutEffect(() => {
    store.set(id, { matches, shown, group });
  }, [store, id, matches, shown, group]);
  useLayoutEffect(() => () => store.remove(id), [store, id]);

  if (!shown) return null;
  return (
    <Pressable
      role="option"
      disabled={disabled}
      aria-disabled={disabled}
      aria-label={ariaLabel}
      {...(ariaChecked === undefined ? {} : { "aria-checked": ariaChecked })}
      // React Native has no `aria-describedby`; react-native-web reads it, the same arrangement
      // as `Input`'s.
      {...(Platform.OS === "web" && ariaDescribedBy !== undefined
        ? { "aria-describedby": ariaDescribedBy }
        : {})}
      onPress={() => onSelect?.(itemValue)}
      className={cn(
        "flex-row items-center gap-2 rounded-sm px-2 py-1.5 active:bg-accent",
        disabled && "opacity-50",
        className,
      )}
    >
      {/* Colour does not inherit on native: the row's icons take theirs through the context and
          a bare string its own `Text`. */}
      <IconClassContext.Provider value="size-4 shrink-0 text-muted-foreground">
        {typeof children === "string" || typeof children === "number" ? (
          <Text numberOfLines={1} className="flex-1 text-sm text-popover-foreground">
            {children}
          </Text>
        ) : (
          children
        )}
      </IconClassContext.Provider>
    </Pressable>
  );
}

function CommandShortcut({ className, children }: CommandShortcutProps) {
  return (
    <Text className={cn("ml-auto text-xs tracking-widest text-muted-foreground", className)}>
      {children}
    </Text>
  );
}

export {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
};

/**
 * The web command list: shadcn's parts over `cmdk`, which owns the roving highlight, the arrow
 * keys, Enter and the fuzzy ranking. `command.tsx` is the native counterpart — cmdk has no React
 * Native build — and `command-base.ts` the contract the two share.
 *
 * Hand-written rather than compiled because there is nothing to compile it from: the native half
 * is a different implementation of the same parts, not a source for this one. Every part takes
 * cmdk's full props, a superset of the contract, so a shadcn call site compiles unchanged; the
 * props the native half does not honour are listed in `command-base.ts`.
 *
 * The Search glyph is `@cubeui/icons`' rather than lucide's directly, so this file is also what an
 * Expo web app can run without a second icon package.
 */
import { Command as CommandPrimitive } from "cmdk";
import type * as React from "react";
import { COMMAND_DIALOG_DESCRIPTION, COMMAND_DIALOG_TITLE } from "@/components/ui/command-base";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Search } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

function Command({ className, ...props }: React.ComponentProps<typeof CommandPrimitive>) {
  return (
    <CommandPrimitive
      data-slot="command"
      className={cn(
        "flex h-full w-full flex-col overflow-hidden rounded-md bg-popover text-popover-foreground",
        className,
      )}
      {...props}
    />
  );
}

function CommandDialog({
  title = COMMAND_DIALOG_TITLE,
  description = COMMAND_DIALOG_DESCRIPTION,
  children,
  className,
  showCloseButton = true,
  ...props
}: React.ComponentProps<typeof Dialog> & {
  title?: string;
  description?: string;
  className?: string;
  showCloseButton?: boolean;
}) {
  return (
    <Dialog {...props}>
      <DialogHeader className="sr-only">
        <DialogTitle>{title}</DialogTitle>
        <DialogDescription>{description}</DialogDescription>
      </DialogHeader>
      <DialogContent
        className={cn("overflow-hidden p-0", className)}
        showCloseButton={showCloseButton}
      >
        <Command className="**:data-[slot=command-input-wrapper]:h-12 [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground [&_[cmdk-group]]:px-2 [&_[cmdk-group]:not([hidden])_~[cmdk-group]]:pt-0 [&_[cmdk-input-wrapper]_svg]:h-5 [&_[cmdk-input-wrapper]_svg]:w-5 [&_[cmdk-input]]:h-12 [&_[cmdk-item]]:px-2 [&_[cmdk-item]]:py-3 [&_[cmdk-item]_svg]:h-5 [&_[cmdk-item]_svg]:w-5">
          {children}
        </Command>
      </DialogContent>
    </Dialog>
  );
}

function CommandInput({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Input>) {
  return (
    <div data-slot="command-input-wrapper" className="flex h-9 items-center gap-2 border-b px-3">
      <Search className="size-4 shrink-0 opacity-50" />
      <CommandPrimitive.Input
        data-slot="command-input"
        className={cn(
          "flex h-10 w-full rounded-md bg-transparent py-3 text-sm outline-hidden placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50",
          className,
        )}
        {...props}
      />
    </div>
  );
}

function CommandList({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.List>) {
  return (
    <CommandPrimitive.List
      data-slot="command-list"
      className={cn("max-h-[300px] scroll-py-1 overflow-x-hidden overflow-y-auto", className)}
      {...props}
    />
  );
}

function CommandEmpty({ ...props }: React.ComponentProps<typeof CommandPrimitive.Empty>) {
  return (
    <CommandPrimitive.Empty
      data-slot="command-empty"
      className="py-6 text-center text-sm"
      {...props}
    />
  );
}

function CommandGroup({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Group>) {
  return (
    <CommandPrimitive.Group
      data-slot="command-group"
      className={cn(
        "overflow-hidden p-1 text-foreground [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-xs [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

function CommandSeparator({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Separator>) {
  return (
    // Decorative: cmdk writes `role="separator"`, which a `listbox` may not hold. Hidden, the
    // rule is still drawn and no longer read. See `command-base.ts`.
    <CommandPrimitive.Separator
      aria-hidden
      data-slot="command-separator"
      className={cn("-mx-1 h-px bg-border", className)}
      {...props}
    />
  );
}

function CommandItem({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.Item>) {
  return (
    <CommandPrimitive.Item
      data-slot="command-item"
      className={cn(
        "relative flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

function CommandShortcut({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="command-shortcut"
      className={cn("ml-auto text-xs tracking-widest text-muted-foreground", className)}
      {...props}
    />
  );
}

export {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
};
